#!/usr/bin/env python3
"""Port mail-inbox onto /opt/liquidgov without replacing the whole http_server or store."""
import gzip, base64, json, shutil
from pathlib import Path
from datetime import datetime, timezone

BLOB = """"""

DATA = json.loads(gzip.decompress(base64.b64decode(BLOB)))
ROOT = Path("/opt/liquidgov")
stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
fail = []

def backup(p):
    if p.exists():
        shutil.copy2(p, str(p) + ".bak-mail-" + stamp)

def once(name, text, old, new):
    n = text.count(old)
    print(name, n)
    if n == 0:
        # already applied?
        if new and text.count(new) >= 1:
            print("  already")
            return text, True
        fail.append(name)
        return text, False
    if n != 1:
        fail.append(name + " count=" + str(n))
        return text, False
    return text.replace(old, new, 1), True

# --- messenger files (safe overwrite) ---
for rel, content in DATA["writes"].items():
    p = ROOT / rel
    if not p.parent.exists():
        fail.append("missing dir " + str(p.parent))
        continue
    backup(p)
    p.write_text(content)
    print("wrote", rel, len(content))

# --- file_store.hpp ---
hpp = ROOT / "libs/liquidgov_file_store/include/liquidgov/platform/file_store.hpp"
if hpp.exists():
    backup(hpp)
    t = hpp.read_text()
    for item in DATA["fs_hpp"]:
        t, _ = once("hpp:" + item["name"], t, item["old"], item["new"])
    if not any(x.startswith("hpp:") for x in fail):
        hpp.write_text(t)
else:
    fail.append("no file_store.hpp")

# --- file_store.cpp ---
cpp = ROOT / "libs/liquidgov_file_store/src/file_store.cpp"
if cpp.exists():
    backup(cpp)
    t = cpp.read_text()
    for item in DATA["fs_cpp"]:
        t, _ = once("cpp:" + item["name"], t, item["old"], item["new"])
    if not any(x.startswith("cpp:") for x in fail):
        cpp.write_text(t)
else:
    fail.append("no file_store.cpp")

# --- http_server.cpp slices ---
src = ROOT / "src/http_server.cpp"
if not src.exists():
    fail.append("no http_server.cpp")
else:
    backup(src)
    t = src.read_text()
    for item in DATA["http_slices"]:
        t, _ = once("http:" + item["name"], t, item["old"], item["new"])
    for item in DATA["http_small"]:
        t, _ = once("http:" + item["name"], t, item["old"], item["new"])
    if not any(x.startswith("http:") for x in fail):
        src.write_text(t)

if fail:
    print("STOP", ", ".join(fail))
    print("Backups: *bak-mail-" + stamp)
    print("NEED_BUILD 0")
    raise SystemExit(1)

print("ok backups bak-mail-" + stamp)
print("NEED_BUILD 1")
